import Foundation

/// Interface text in the viewer's language. The key is the Traditional Chinese original; translations
/// live in Resources/<lang>.lproj/Localizable.strings, generated by scripts/localize.py. A missing
/// translation shows the original rather than nothing. Arguments fill %@ in order.
func L(_ key: String, _ arguments: CVarArg...) -> String {
    let format = Bundle.main.localizedString(forKey: key, value: key, table: nil)
    return arguments.isEmpty ? format : String(format: format, arguments: arguments)
}

/// The language the interface is showing: "en", "zh-Hant" or "zh-Hans".
var interfaceLanguage: String { Bundle.main.preferredLocalizations.first ?? "zh-Hant" }
